def symmetrize2(grid):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    for _ in range(60):
        S=imgs(g); changed=False
        for i in range(h):
            for j in range(w):
                c=Counter(S[k][i][j] for k in range(8))
                top=c.most_common()
                if len(top)>1 and top[0][1]==top[1][1]:
                    continue  # tie: keep current
                if top[0][0]!=g[i][j]:
                    g[i][j]=top[0][0]; changed=True
        if not changed: break
    return g
